-- Recetario compartido entre sedes. Únicamente el admin modifica y publica.
create table public.gf_recipe_settings (
 id boolean primary key default true check (id),
 enabled boolean not null default true
);
insert into public.gf_recipe_settings(id,enabled) values(true,true);
create table public.gf_recipes (
 id uuid primary key default gen_random_uuid(),
 source_key text unique,
 title text not null check(length(btrim(title)) between 1 and 200),
 category text not null default 'Otros' check(length(category) between 1 and 80),
 image_url text not null default '' check(length(image_url)<=2000),
 minutes integer check(minutes between 0 and 1440),
 protein_g numeric check(protein_g between 0 and 10000),
 carbs_g numeric check(carbs_g between 0 and 10000),
 fat_g numeric check(fat_g between 0 and 10000),
 ingredients text[] not null check(cardinality(ingredients) between 1 and 200),
 steps text[] not null check(cardinality(steps) between 1 and 200),
 source text not null default '' check(length(source)<=300),
 is_hidden boolean not null default false,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table public.gf_recipe_settings enable row level security;
alter table public.gf_recipes enable row level security;
revoke all on public.gf_recipe_settings, public.gf_recipes from anon, public;
grant select,update on public.gf_recipe_settings to authenticated;
grant select,insert,update,delete on public.gf_recipes to authenticated;
create policy recipe_settings_read on public.gf_recipe_settings for select to authenticated
 using ((select public.gf_current_role()) in ('admin','coadmin','profe','cliente'));
create policy recipe_settings_admin_update on public.gf_recipe_settings for update to authenticated
 using ((select public.gf_current_role())='admin') with check ((select public.gf_current_role())='admin');
create policy recipes_read on public.gf_recipes for select to authenticated
 using ((select public.gf_current_role())='admin' or (
 (select public.gf_current_role()) in ('coadmin','profe','cliente') and not is_hidden
 and exists(select 1 from public.gf_recipe_settings where id and enabled)));
create policy recipes_admin_insert on public.gf_recipes for insert to authenticated
 with check ((select public.gf_current_role())='admin');
create policy recipes_admin_update on public.gf_recipes for update to authenticated
 using ((select public.gf_current_role())='admin') with check ((select public.gf_current_role())='admin');
create policy recipes_admin_delete on public.gf_recipes for delete to authenticated
 using ((select public.gf_current_role())='admin');
create function private.gf_recipe_updated_at() returns trigger language plpgsql set search_path='' as $$
begin new.updated_at=now(); return new; end; $$;
revoke all on function private.gf_recipe_updated_at() from public,anon,authenticated;
create trigger recipe_updated_at before update on public.gf_recipes for each row execute function private.gf_recipe_updated_at();

-- Importación única: no reemplaza futuras ediciones ni vuelve a crear recetas eliminadas al desplegar.
insert into public.gf_recipes (source_key,title,category,image_url,minutes,protein_g,carbs_g,fat_g,ingredients,steps,source)
select source_key,title,category,image_url,minutes,protein_g,carbs_g,fat_g,ingredients,steps,source
from jsonb_to_recordset($recetas$[{"source_key": "myfitcoach:1", "title": "Tortitas de bayas", "category": "Desayunos", "protein_g": 31, "carbs_g": 88, "fat_g": 9, "minutes": 30, "ingredients": ["1 Huevo", "2 Claras de Huevo", "35 g Requesón", "120 g Plátano", "70 g Harina de Espelta", "0.5 paquete Polvo de Hornear", "40 g Frambuesas", "40 g Arándanos", "2 cda Miel o Sirope de Agave"], "steps": ["Separa dos huevos y colócalos en un bol.", "Bate las claras de huevo con un batidor o una batidora hasta que estén firmes.", "A continuación, añade el huevo entero, la cuajada, el plátano, la harina de espelta y la levadura en polvo, y mezcla con una batidora para formar una masa ligeramente espesa.", "Mientras tanto, calienta una sartén a fuego alto (3-4 minutos). A continuación, engrásala ligeramente y vierte la masa en la sartén a fuego lento.", "Apila los tortitas terminados y sírvelos con bayas y miel."], "image_url": "/images/recipes/1.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:2", "title": "Avena con frambuesa", "category": "Desayunos", "protein_g": 31, "carbs_g": 38, "fat_g": 7, "minutes": 10, "ingredients": ["50 g Avena", "30 g Proteína en Polvo (Vainilla)", "1 Vaina de Vainilla o Gotas de Sabor a Vainilla", "15 g Eritritol", "100 g Frambuesas"], "steps": ["Pon a hervir la avena en una olla con agua y la proteína en polvo.", "Añade eritritol (no es estrictamente necesario, si no tienes eritritol a mano, simplemente omítelo) y gotas de sabor."], "image_url": "/images/recipes/2.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:3", "title": "Avena con plátano y arándanos", "category": "Desayunos", "protein_g": 31, "carbs_g": 56, "fat_g": 7, "minutes": 10, "ingredients": ["50 g Avena", "30 g Proteína en Polvo (Vainilla)", "1 Vaina de Vainilla o Gotas de Sabor a Vainilla", "15 g Eritritol", "100 g Plátano", "40 g Arándanos"], "steps": ["Hierve la avena en una olla con agua y la proteína en polvo.", "Añade eritritol (no es estrictamente necesario, si no tienes eritritol a mano, simplemente omítelo) y gotas de sabor.", "Vierte la papilla cocida en un bol y añade el plátano y los arándanos."], "image_url": "/images/recipes/3.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:4", "title": "Avena con plátano y chocolate", "category": "Desayunos", "protein_g": 45, "carbs_g": 84, "fat_g": 11, "minutes": 10, "ingredients": ["100 g Avena", "40 g Proteína en Polvo (Chocolate)", "15 g Eritritol", "100 g Plátano"], "steps": ["Hierve la avena en una olla con agua y la proteína en polvo, y añade eritritol (no es estrictamente necesario, si no tienes eritritol a mano, simplemente omítelo).", "Vierte la avena cocida en un bol y añade el plátano."], "image_url": "/images/recipes/4.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:5", "title": "Tortitas de vainilla", "category": "Desayunos", "protein_g": 55, "carbs_g": 110, "fat_g": 11, "minutes": 30, "ingredients": ["1 Huevo", "3 Claras de Huevo", "30 g Proteína en Polvo", "60 ml Leche", "120 Plátano", "90 g Harina de Espelta", "0.5 paquete Polvo de Hornear", "2 cda Miel o Sirope de Agave"], "steps": ["Separa tres huevos y colócalos en un bol. Bate las claras de huevo con un batidor o una batidora hasta que estén firmes.", "A continuación, añade el huevo entero, la leche, el plátano y la levadura en polvo, y mezcla bien.", "A continuación, añade la harina de espelta y la proteína en polvo, y mezcla con una batidora para formar una masa ligeramente espesa y fluida.", "Mientras tanto, calienta una sartén a fuego alto (3-4 minutos). A continuación, engrasa ligeramente y vierte la masa en la sartén a fuego lento. Una vez que se formen burbujas en la superficie, dale la vuelta a los tortitas.", "Apila los tortitas terminados y sírvelos con miel."], "image_url": "/images/recipes/5.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:6", "title": "Tortilla de claras de huevo", "category": "Desayunos", "protein_g": 33, "carbs_g": 7, "fat_g": 10, "minutes": 15, "ingredients": ["1 Huevo", "7 Claras de Huevo", "0.5 Cebolla", "0.5 Ajo", "Cebollino", "1 Tomate", "1 Pimiento", "Sal y Pimienta"], "steps": ["Corta la cebolla y el diente de ajo en dados y saltéalos ligeramente en una sartén con un poco de aceite. Mientras tanto, corta el tomate y el pimiento en trozos pequeños.", "A continuación, separa las yemas de siete huevos y colócalas junto con un huevo entero (en la dieta, puedes sustituir el huevo entero por otra clara de huevo) en un bol, sazonando ligeramente con pimienta y sal.", "Añade los huevos sazonados, el tomate y el pimiento a la cebolla y el ajo en la sartén y cocina."], "image_url": "/images/recipes/6.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:7", "title": "Tazón de batido con chía", "category": "Desayunos", "protein_g": 43, "carbs_g": 25, "fat_g": 9, "minutes": 5, "ingredients": ["200 g Bayas (congeladas)", "30 g Proteína en Polvo (Vainilla)", "100 g Requesón Bajo en Grasa", "100 ml Leche de Coco", "5 g Semillas de Chía"], "steps": ["Añade las bayas, la proteína en polvo, la cuajada baja en grasa y la leche de coco a una batidora y bate los ingredientes durante unos 30-60 segundos.", "A continuación, vierte el batido en un bol y espolvorea con semillas de chía.", "Disfruta del batido como bebida o cómelo con una cuchara como una mezcla espesa."], "image_url": "/images/recipes/7.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:8", "title": "Batido Micro Kick", "category": "Snacks y meriendas", "protein_g": 4, "carbs_g": 51, "fat_g": 1, "minutes": 5, "ingredients": ["100 g Lechuga de Cordero", "1 cdita Hierba de Trigo", "1 cdita Semillas de Cáñamo", "120 g Plátano", "100 g Manzana", "1 cdita Semillas de Chía", "20 ml Jugo de Limón", "20 g Arándanos"], "steps": ["Pela el plátano, corta la manzana en ocho trozos y añádelos a una batidora junto con el pasto de trigo, las semillas de cáñamo, el zumo de limón, la canónigos y las semillas de chía. Bate bien durante 30-60 segundos.", "Vierte la mezcla en un vaso y decora con unos cuantos arándanos."], "image_url": "/images/recipes/8.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:9", "title": "Batido de plátano para volumen", "category": "Snacks y meriendas", "protein_g": 62, "carbs_g": 163, "fat_g": 16, "minutes": 5, "ingredients": ["360 g Plátano", "85 g Avena", "250 g Requesón Bajo en Grasa", "400 ml Leche"], "steps": ["Coloca el plátano pelado, la avena, la cuajada baja en grasa y la leche en una batidora y bate durante 30-60 segundos (dependiendo de la potencia de la batidora). Si el batido está demasiado espeso, añade más leche o agua según sea necesario.", "Vierte el batido en un vaso y decora con las rodajas de plátano restantes."], "image_url": "/images/recipes/9.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:10", "title": "Batido de chocolate y almendras", "category": "Snacks y meriendas", "protein_g": 88, "carbs_g": 116, "fat_g": 38, "minutes": 5, "ingredients": ["50 g Chocolate", "30 g Almendras", "60 g Proteína en Polvo (Chocolate)", "100 g Copos de Espelta", "400 g Leche"], "steps": ["Rompe el chocolate en trozos pequeños y añádelos a una batidora junto con las almendras, la proteína en polvo, los copos de espelta y la leche. Bate durante 30-60 segundos (dependiendo de la potencia de la batidora). Si el batido está demasiado espeso, añade más leche o agua según sea necesario.", "Vierte el batido en un vaso y disfrútalo."], "image_url": "/images/recipes/10.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:11", "title": "Batido de fresa y vainilla", "category": "Snacks y meriendas", "protein_g": 45, "carbs_g": 127, "fat_g": 26, "minutes": 5, "ingredients": ["300 g Fresas (congeladas)", "125 g Requesón Bajo en Grasa", "150 g Piña", "50 g Avena", "250 ml Helado de Vainilla", "500 ml Leche"], "steps": ["Añade las fresas, la avena, el helado de vainilla, la piña, la cuajada baja en grasa y la leche a una batidora y bate durante 30-60 segundos (dependiendo de la potencia de la batidora). Si el batido está demasiado espeso, añade más leche o agua según sea necesario.", "Vierte el batido en un vaso y disfrútalo."], "image_url": "/images/recipes/11.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:12", "title": "Batido Bomba Amarilla", "category": "Snacks y meriendas", "protein_g": 48, "carbs_g": 178, "fat_g": 16, "minutes": 5, "ingredients": ["300 g Plátano", "130 g Mango", "150 g Piña", "80 g Avena", "125 g Requesón Bajo en Grasa", "500 ml Leche"], "steps": ["Añade los plátanos pelados, el mango, la avena, la piña, la cuajada baja en grasa y la leche a una batidora y bate durante 30-60 segundos (dependiendo de la potencia de la batidora). Si el batido está demasiado espeso, añade más leche o agua según sea necesario.", "Vierte el batido en un vaso y disfrútalo."], "image_url": "/images/recipes/12.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:13", "title": "Cuajada con miel", "category": "Snacks y meriendas", "protein_g": 30, "carbs_g": 25, "fat_g": 1, "minutes": 2, "ingredients": ["250 g Requesón Bajo en Grasa", "2 cda Miel", "4 cda Agua", "1 cdita Eritritol"], "steps": ["Coloca la cuajada baja en grasa en un bol y mézclala con la miel, cuatro cucharadas de agua y un poco de eritritol (o sustituto del azúcar).", "A continuación, sirve la cuajada baja en grasa en un bol, rociada con miel."], "image_url": "/images/recipes/13.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:14", "title": "Mug cake blanco", "category": "Desayunos", "protein_g": 30, "carbs_g": 75, "fat_g": 8, "minutes": 10, "ingredients": ["120 g Plátano", "100 g Mezcla de Bayas (congeladas)", "30 g Avena", "30 g Harina de Espelta", "30 g Proteína en Polvo (Vainilla)", "0.5 cdita Polvo de Hornear", "80 ml Leche de Almendras", "40 ml Sirope de Chocolate (sin azúcar)"], "steps": ["Mezcla todos los ingredientes en un bol pequeño y remuévelos bien.", "Luego, caliéntalos en el microondas durante 2 minutos.", "Mientras tanto, corta el plátano en rodajas finas y uniformes.", "Después, pon el pastel de taza en un plato y decóralo con las rodajas de plátano, las bayas y el sirope de chocolate al gusto."], "image_url": "/images/recipes/14.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:15", "title": "Pastel Polska", "category": "Desayunos", "protein_g": 48, "carbs_g": 84, "fat_g": 10, "minutes": 30, "ingredients": ["200 g Mezcla de Bayas (congeladas)", "125 g Harina de Avena Integral", "10 g Harina de Coco", "1 Huevo", "150 ml Claras de Huevo", "30 g Proteína en Polvo (Chocolate)", "0.5 cdita Polvo de Hornear", "30 g Yogur"], "steps": ["Precalienta el horno a 170 °C (340 °F).", "Mientras tanto, mezcla la avena integral y la harina de coco, la levadura en polvo, el huevo, la clara de huevo y la proteína en polvo en un bol hasta obtener una consistencia similar a la de la masa.", "A continuación, añade las bayas y mézclalas.", "Por último, vierte la masa en una fuente de horno y hornéala durante 20 minutos."], "image_url": "/images/recipes/15.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:16", "title": "Tostada con huevos revueltos al curry y queso", "category": "Desayunos", "protein_g": 66, "carbs_g": 36, "fat_g": 23, "minutes": 15, "ingredients": ["8 Claras de Huevo", "2 Huevos", "50 g Queso Bajo en Grasa", "3 g Aceite de Coco", "75 g Tostada de Grano Entero", "Polvo de Curry", "Sal y Pimienta"], "steps": ["Separa las yemas de ocho huevos y mezcla solo las claras con dos huevos enteros en un bol.", "Sazona la mezcla con curry en polvo, pimienta y sal.", "Luego, cocina todo en una sartén con un poco de aceite de coco y, al cabo de un rato, añade el queso."], "image_url": "/images/recipes/16.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:17", "title": "Sándwich de pollo", "category": "Snacks y meriendas", "protein_g": 32, "carbs_g": 62, "fat_g": 4, "minutes": 5, "ingredients": ["180 g Pan Integral", "25 g Hojas de Lechuga", "20 g Pepino", "50 g Queso Crema Bajo en Grasa", "80 g Pechuga de Pollo"], "steps": ["Primero, corta el pepino en trozos pequeños y luego corta cada trozo por la mitad.", "A continuación, unta queso crema bajo en grasa en una rebanada de pan integral y cúbrela con la pechuga de pollo, la ensalada de hojas y el pepino. Cúbrelo con la otra rebanada de pan y disfrútalo."], "image_url": "/images/recipes/17.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:18", "title": "Ensalada de atún", "category": "Platos principales", "protein_g": 62, "carbs_g": 16, "fat_g": 12, "minutes": 5, "ingredients": ["300 g Atún enlatado (en agua)", "30 g Cebolla", "120 g Tomates Cherry", "50 g Frijoles Rojos", "150 g Hoja de Lechuga", "20 g Semillas de Girasol", "Sal y Pimienta"], "steps": ["Pica la cebolla finamente, corta los tomates cherry en cuartos y mézclalos con la lechuga.", "A continuación, añade el atún y las alubias rojas, y sazona la ensalada con semillas de girasol, sal y pimienta."], "image_url": "/images/recipes/18.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:19", "title": "Bistec con gajos de papa", "category": "Platos principales", "protein_g": 55, "carbs_g": 60, "fat_g": 24, "minutes": 45, "ingredients": ["400 g Papas", "220 g Filete de Res", "10 ml Aceite de Oliva", "Ramita de Romero", "Sal y Pimienta", "Pimienta de Cayena"], "steps": ["Corta las patatas en gajos y espárcelas uniformemente en una bandeja de horno.", "En un bol, mezcla el aceite de oliva con sal, pimienta y pimienta de cayena, y utiliza un pincel para aplicar la mezcla a los gajos de patata.", "Espolvorea un poco de romero sobre las patatas y hornéalas durante 12-15 minutos a 180 °C en un horno precalentado.", "Dora el filete de ternera en una sartén por ambos lados.", "Por último, coloca el filete y los gajos de patata en un plato."], "image_url": "/images/recipes/19.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:20", "title": "Chili con carne", "category": "Platos principales", "protein_g": 104, "carbs_g": 71, "fat_g": 37, "minutes": 50, "ingredients": ["300 g Tartar de Res", "500 g Tomates (colados)", "30 g Cebolla", "150 g Maíz", "255 g Frijoles Rojos", "100 g Queso Crema Bajo en Grasa", "Pimienta de Cayena y Copos de Chile", "5 ml Aceite de Oliva"], "steps": ["Cocina bien el tartar de ternera en una sartén con un poco de aceite de oliva.", "A continuación, añade todos los ingredientes a una olla, sazónalos con pimienta de cayena, hojuelas de chile y sal, y déjalos hervir a fuego lento durante 35-40 minutos."], "image_url": "/images/recipes/20.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:21", "title": "Espaguetis a la boloñesa", "category": "Platos principales", "protein_g": 65, "carbs_g": 186, "fat_g": 18, "minutes": 20, "ingredients": ["180 g Tartar de Res", "0.5 Tomate", "30 g Cebolla", "1 vaso Salsa de Tomate", "200 Espagueti", "Sal", "Pimienta"], "steps": ["Cocina los espaguetis según las instrucciones del paquete en una olla con agua caliente ligeramente salada. Mientras tanto, cocina el tartar de ternera en una sartén con un poco de aceite.", "Añade la cebolla picada y saltea ligeramente.", "A continuación, añade la salsa de tomate y el tomate picado, y deja que se cocine durante 3-4 minutos.", "Ahora, coloca los espaguetis en un plato y vierte la salsa sobre ellos."], "image_url": "/images/recipes/21.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:22", "title": "Pizza fitness", "category": "Platos principales", "protein_g": 113, "carbs_g": 204, "fat_g": 40, "minutes": 20, "ingredients": ["1 Kit de Pizza", "2 Tomates", "2 Mozzarella", "80 g Salami de Res"], "steps": ["Precalienta el horno a 180 °C. Extiende la masa en una bandeja de horno forrada con papel de hornear y esparce la salsa de tomate uniformemente sobre ella.", "Corta el tomate en rodajas y colócalo junto con el salami de ternera sobre la masa.", "A continuación, distribuye la mozzarella uniformemente sobre la masa cubierta.", "Por último, mete la bandeja de horno en el horno durante unos 12 minutos."], "image_url": "/images/recipes/22.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:23", "title": "Cazuela de chili con carne", "category": "Platos principales", "protein_g": 154, "carbs_g": 212, "fat_g": 40, "minutes": 45, "ingredients": ["200 g Penne", "180 g Tartar de Res", "150 g Queso Bajo en Grasa", "500 g Tomates (colados)", "60 g Cebolla", "150 g Maíz", "255 g Frijoles Rojos", "120 g Queso Crema"], "steps": ["Cuece los penne y, al mismo tiempo, dora el tartar de ternera con un poco de aceite de oliva y la cebolla picada.", "A continuación, refina el tartar de ternera con los tomates colados.", "Mientras se cuece a fuego lento, mezcla el queso crema.", "A continuación, añade los penne a la olla y mezcla todo bien.", "Coloca los penne con el chile en una cazuela y espolvorea con queso bajo en grasa. Por último, hornea la cazuela en un horno precalentado a 180 °C (350 °F) durante 10-12 minutos."], "image_url": "/images/recipes/23.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:24", "title": "Pimientos rellenos", "category": "Platos principales", "protein_g": 77, "carbs_g": 126, "fat_g": 17, "minutes": 45, "ingredients": ["3 Pimiento", "300 g Tartar de Res", "150 g Arroz", "60 g Cebolla", "Sal", "Pimienta", "Pimentón"], "steps": ["Cuece el arroz según las instrucciones del paquete en una olla con agua salada. Mientras tanto, dora el tartar de ternera junto con las cebollas y sazónalo con pimienta, sal y pimentón.", "Añade el arroz cocido al tartar de ternera y mezcla todo bien.", "A continuación, corta la parte superior del pimiento y vacíalo.", "Rellena el pimiento con la mezcla de tartar de ternera y arroz, vuelve a colocar la tapa en el pimiento y ponlo en una fuente de horno. Hornea durante unos 10 minutos en un horno precalentado a 150 °C (300 °F)."], "image_url": "/images/recipes/24.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:25", "title": "Hamburguesa de pollo", "category": "Platos principales", "protein_g": 68, "carbs_g": 66, "fat_g": 21, "minutes": 25, "ingredients": ["200 g Pechuga de Pollo", "2 Panecillos de Hamburguesa", "20 g Salsa de Curry y Mango", "40 g Queso en Lonchas Bajo en Grasa", "20 g Lechuga", "30 g Tomate", "30 g Cebolla"], "steps": ["Cocina la pechuga de pollo en una sartén. Corta los panes de hamburguesa y colócalos en el horno precalentado a 350 °F (180 °C) durante 2 minutos.", "Unta la salsa de curry y mango en el pan y añade lechuga, dos rodajas de tomate y una loncha de queso bajo en grasa.", "A continuación, coloca la pechuga de pollo cocida encima y adórnalo con un poco de lechuga y unos trozos de cebolla.", "Unta un poco de salsa de curry y mango en la otra mitad del pan y úsala para cubrir la hamburguesa."], "image_url": "/images/recipes/25.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:26", "title": "Curry tailandés con arroz", "category": "Platos principales", "protein_g": 60, "carbs_g": 119, "fat_g": 37, "minutes": 35, "ingredients": ["200 g Pechuga de Pollo", "125 g Arroz", "80 g Judías Verdes", "4 cda Pasta de Curry", "0.4 L Leche de Coco (light)", "10 ml Aceite de Oliva o Sésamo", "60 g Cebolla", "1 Chile"], "steps": ["Cocina el arroz según las instrucciones del paquete en una olla con agua con sal. Saltea la pechuga de pollo en una sartén con un poco de aceite.", "Corta la cebolla, añádela a la sartén con la pechuga de pollo y saltea hasta que esté transparente.", "En un bol, mezcla la mitad de la leche de coco con la pasta de curry, viértela sobre las cebollas y déjala hervir.", "Añade la leche de coco restante y la pechuga de pollo, y deja que hierva a fuego lento con la tapa cerrada durante unos 10 minutos.", "Añade las judías verdes y deja que hiervan a fuego lento durante otros 3 minutos.", "Sirve el arroz cocido y el curry tailandés juntos en un bol."], "image_url": "/images/recipes/26.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:27", "title": "Sándwich de salmón, aguacate y huevo", "category": "Snacks y meriendas", "protein_g": 16, "carbs_g": 42, "fat_g": 19, "minutes": 10, "ingredients": ["50 g Guacamole", "70 g Salmón", "20 g Tomate", "1 Huevo", "80 g Bollos de Espelta"], "steps": ["Corta un pan de espelta por la mitad y unta guacamole en ambas mitades.", "Coloca dos rodajas de tomate y medio huevo (en rodajas) en cada mitad.", "Espolvorea un poco de sal sobre las rodajas de huevo y cúbrelas con salmón ahumado."], "image_url": "/images/recipes/27.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:28", "title": "Sándwich de aguacate y huevo", "category": "Snacks y meriendas", "protein_g": 15, "carbs_g": 44, "fat_g": 18, "minutes": 10, "ingredients": ["1 Huevo", "30 g Aguacate", "5 g Rúcula", "60 g Pan de Grano Entero", "Sal", "Pimienta"], "steps": ["Primero, tuesta ligeramente la rebanada de pan integral en una tostadora.", "Pela medio aguacate, córtalo en cuatro o cinco rodajas del mismo tamaño y colócalas una al lado de la otra en el pan.", "A continuación, corta un huevo cocido en rodajas del grosor que prefieras y distribúyelas también sobre el pan.", "Sazona todo con un poco de sal y pimienta y, si quieres, decora con un poco de rúcula."], "image_url": "/images/recipes/28.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:29", "title": "Sándwich de huevos revueltos con salmón", "category": "Snacks y meriendas", "protein_g": 18, "carbs_g": 21, "fat_g": 11, "minutes": 10, "ingredients": ["60 g Pan de Centeno", "30 g Salmón", "1 Huevo", "1 cdita Leche", "Cebollino", "Sal y Pimienta"], "steps": ["Rompe el huevo y fríelo en una sartén con un poco de aceite y una cucharadita de leche, removiendo bien.", "A continuación, corta el salmón ahumado en tiras.", "Cubre el pan de centeno con el huevo revuelto y el salmón ahumado, y sazona al gusto con sal, pimienta y cebollino picado."], "image_url": "/images/recipes/29.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:30", "title": "Receta de masa para pizza", "category": "Platos principales", "protein_g": 20, "carbs_g": 146, "fat_g": 4, "minutes": 60, "ingredients": ["200 g Harina de Espelta", "0.33 paquete Levadura", "1 cdita Sal"], "steps": ["Coloca la harina de espelta en un bol y haz un hueco en el centro.", "En otro bol, mezcla 100 ml de agua tibia con la levadura.", "Añade la levadura y una pizca de sal al hueco de la harina.", "Mezcla todo con una batidora (utilizando un accesorio de gancho para masa, si está disponible) y luego amasa bien la masa a mano.", "Cubre la masa y déjala reposar durante unos 30-40 minutos.", "Por último, extiende la masa en una bandeja de horno y métela en el horno precalentado a 200 °C (390 °F) durante 12-15 minutos."], "image_url": "/images/recipes/30.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:31", "title": "Albóndigas picantes", "category": "Platos principales", "protein_g": 68, "carbs_g": 17, "fat_g": 25, "minutes": 45, "ingredients": ["300 g Tartar de Res", "60 g Cebolla", "400 g Tomates (pelados)", "60 g Pimiento", "2 cdita Sambal Oelek", "10 ml Aceite de Oliva"], "steps": ["Corta la cebolla en cubos pequeños.", "Sazona el tartar de ternera con sal y pimienta, y amásalo con la cebolla picada.", "Forma entre seis y siete albóndigas de tamaño similar con el tartar de ternera.", "Fríe las albóndigas en una sartén con un poco de aceite de oliva. Mientras tanto, pica finamente los tomates pelados y el pimiento y añádelos a la sartén (una vez que las albóndigas estén bien hechas) junto con el jugo de la lata.", "Añade dos cucharaditas de sambal oelek y deja que todo hierva a fuego lento durante unos 5-7 minutos."], "image_url": "/images/recipes/31.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:32", "title": "Tortilla de verduras", "category": "Desayunos", "protein_g": 54, "carbs_g": 10, "fat_g": 22, "minutes": 45, "ingredients": ["2 Huevos", "8 Claras de Huevo", "80 g Tomates Cherry", "250 g Brócoli", "15 g Pimiento", "10 ml Aceite de Oliva", "Sal y Pimienta"], "steps": ["Cocina el brócoli según las instrucciones del paquete.", "Separa las yemas de ocho huevos y pon las claras junto con dos huevos enteros en un bol.", "Corta el pimiento en cubos pequeños, corta los tomates cherry por la mitad y añade ambos al bol.", "Fríe la mezcla junto con el brócoli cocido en una sartén con un poco de aceite.", "Sazona la tortilla con sal y pimienta al gusto."], "image_url": "/images/recipes/32.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:33", "title": "Wraps de espinaca y feta", "category": "Platos principales", "protein_g": 51, "carbs_g": 48, "fat_g": 21, "minutes": 30, "ingredients": ["3 Envolturas de Proteína", "1 Cebolla", "1 Ajo", "250 g Espinacas Baby (frescas o congeladas)", "100 g Queso Feta (bajo en grasa)", "1 cdita Aceite de Oliva", "Perejil", "Sal y Pimienta", "Nuez Moscada", "1 Yema de Huevo", "Sésamo"], "steps": ["Precalienta el horno a 180 °C. Primero, saltea ligeramente los trozos de cebolla cortados en dados y el ajo picado en aceite de oliva, luego añade las espinacas tiernas. Sazona con sal, pimienta y una pizca de nuez moscada y retíralo del fuego.", "Desmenuza el queso feta con los dedos y mézclalo con el perejil picado. Añade la mezcla de espinacas ligeramente enfriada y remueve bien.", "Unta la mezcla de espinacas y queso feta en el centro del wrap de proteína y enróllalo."], "image_url": "/images/recipes/33.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:34", "title": "Nachos con carne y queso", "category": "Platos principales", "protein_g": 112, "carbs_g": 146, "fat_g": 66, "minutes": 45, "ingredients": ["140 g Tortilla Chips", "400 g Frijoles Negros (en Salsa de Chile)", "180 g Tartar de Res", "150 g Queso para Pizza (bajo en grasa)", "10 g Salsa Sriracha", "5 ml Aceite de Oliva"], "steps": ["Dora el tartar de ternera en una sartén con un chorrito de aceite.", "A continuación, añade los frijoles negros con salsa a la sartén y sazona la mezcla con una cucharada de salsa Sriracha.", "Esparce la mitad de los chips de tortilla en una fuente de horno y distribuye el tartar de ternera y la mezcla de frijoles sobre ellos.", "Espolvorea una fina capa de queso para pizza por encima (unos 50 g).", "Esparce los chips de tortilla restantes por encima y espolvorea con el resto del queso (unos 100 g).", "Por último, hornea el plato durante unos 10 minutos a 150 °C."], "image_url": "/images/recipes/34.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:35", "title": "Pollo agridulce", "category": "Platos principales", "protein_g": 151, "carbs_g": 248, "fat_g": 10, "minutes": 45, "ingredients": ["500 g Pechuga de Pollo", "60 g Pimiento", "150 g Brócoli", "60 g Zanahorias", "1 Cebolla de Verdeo", "300 g Piña", "300 ml Jugo de Naranja", "5 cdita Salsa de Soja", "3 cda Vinagre", "4 cda Pasta de Tomate", "200 g Arroz", "1 cdita Eritritol"], "steps": ["Cocina el brócoli y el arroz según las instrucciones del paquete.", "Corta la pechuga de pollo en trozos pequeños.", "Lava y pica las cebolletas y el pimiento. Pela las zanahorias y córtalas en tiras finas.", "Dora la pechuga de pollo en una sartén grande.", "Sazona al gusto con curry, sal y pimienta.", "Desglasar con zumo de naranja. Añadir salsa de soja, vinagre, pasta de tomate, piña y eritritol. Remueve bien hasta que la pasta de tomate se haya disuelto.", "Deja que hierva a fuego medio con la tapa cerrada durante unos 10-12 minutos.", "Coloca la pechuga de pollo, la salsa y el arroz en un plato o en cuencos."], "image_url": "/images/recipes/35.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:36", "title": "Burrito de pollo", "category": "Platos principales", "protein_g": 61, "carbs_g": 79, "fat_g": 11, "minutes": 30, "ingredients": ["200 g Pollo", "20 g Lechuga", "40 g Maíz", "0.5 Pimiento", "30 g Crema Agria (bajo en grasa)", "2 Tortilla"], "steps": ["Dora el pollo en una sartén con un chorrito de aceite de oliva.", "Calienta las tortillas individualmente durante aproximadamente 1 minuto en un plato en el microondas y corta el pimiento en cubos pequeños.", "Luego, esparce todo uniformemente en el centro de la tortilla y enróllala como un burrito."], "image_url": "/images/recipes/36.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:37", "title": "Tarta flambée fitness", "category": "Platos principales", "protein_g": 48, "carbs_g": 23, "fat_g": 7, "minutes": 30, "ingredients": ["1 Tortilla de Trigo Integral", "150 g Cubos de Jamón", "50 g Queso Crema Bajo en Grasa con Hierbas", "40 g Cebolla", "Sal y Pimienta"], "steps": ["Dobla ligeramente los bordes de la tortilla integral y úntala con el queso crema bajo en grasa con hierbas. Corta la cebolla en cubos pequeños, espárcela junto con los cubos de jamón en la tortilla de trigo integral cubierta de queso crema y sazona al gusto con sal y pimienta.", "Hornea durante 5-7 minutos a 150 °C (300 °F) en el horno precalentado."], "image_url": "/images/recipes/37.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:38", "title": "Ensalada de pollo y batata", "category": "Platos principales", "protein_g": 53, "carbs_g": 57, "fat_g": 12, "minutes": 30, "ingredients": ["250 g Batatas", "200 g Pollo", "150 g Lechuga de Cordero", "60 g Tomates", "40 g Champiñones", "10 ml Aceite de Oliva", "Sal y Pimienta", "Especias de Paprika y Chile"], "steps": ["Corta los boniatos en tiras y mézclalos en un bol con un poco de aceite, sal, pimienta, pimentón y chile en polvo. Spread the sweet potatoes evenly on a baking sheet and bake for 15-20 minutes at 350°F (180°C) in the preheated oven.", "Meanwhile, cook the chicken with some oil in a pan and slice the tomatoes and mushrooms.", "Finally, place everything in a bowl and enjoy."], "image_url": "/images/recipes/38.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:39", "title": "Pasta con jamón y feta", "category": "Platos principales", "protein_g": 50, "carbs_g": 109, "fat_g": 15, "minutes": 25, "ingredients": ["150 g Penne (Grano Entero)", "75 g Cubos de Jamón (magro)", "100 g Queso Feta (bajo en grasa)", "40 g Cebolla", "60 g Tomate", "150 g Tomate (colado)", "5 ml Aceite de Oliva", "Sal y Pimienta"], "steps": ["Cocina los penne integrales según las instrucciones del paquete.", "A continuación, corta el tomate y la cebolla en trozos pequeños.", "En una sartén, sofríe la cebolla con los dados de jamón y un poco de aceite.", "Después, añade el tomate picado y el tomate colado y sazona con pimienta y sal.", "Por último, sirve el penne integral y la salsa en un plato y desmenuza el queso feta por encima."], "image_url": "/images/recipes/39.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:40", "title": "Wrap de pollo y feta", "category": "Platos principales", "protein_g": 50, "carbs_g": 29, "fat_g": 15, "minutes": 15, "ingredients": ["1 Tortilla de Trigo Integral", "150 g Pollo", "75 g Mezcla de Ensalada", "50 g Queso Feta (bajo en grasa)", "15 g Ketchup (light)", "5 ml Aceite de Oliva", "Sal y Pimienta"], "steps": ["Cocina el pollo con un poco de aceite en una sartén y sazónalo con sal y pimienta.", "A continuación, coloca la ensalada y el pollo en el centro de la tortilla de trigo integral.", "Desmenuza el queso feta en trozos pequeños y espárcelo sobre el pollo y la ensalada.", "A continuación, unta un poco de kétchup sobre la tortilla y enróllala."], "image_url": "/images/recipes/40.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:41", "title": "Burrito mexicano", "category": "Platos principales", "protein_g": 75, "carbs_g": 168, "fat_g": 26, "minutes": 30, "ingredients": ["200 g Pollo", "125 g Arroz Integral", "100 g Frijoles Rojos", "50 g Crema Agria (light)", "50 g Guacamole", "5 g Salsa Sriracha", "2 Tortilla", "5 ml Aceite de Oliva", "Especia de Paprika", "Sal"], "steps": ["Cocina el arroz según las instrucciones del paquete y cocina el pollo con sal, condimento de pimentón y un poco de aceite en una sartén.", "Calienta las tortillas individualmente durante aproximadamente 1 minuto en un plato en el microondas.", "Coloca los ingredientes juntos en el centro de la tortilla y luego enróllala."], "image_url": "/images/recipes/41.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:42", "title": "Tortitas de atún", "category": "Platos principales", "protein_g": 91, "carbs_g": 1, "fat_g": 24, "minutes": 15, "ingredients": ["390 g Atún enlatado (en su propio jugo)", "60 g Cebolla", "10 ml Aceite de Oliva", "2 Huevos", "Sal y Pimienta"], "steps": ["Corta la cebolla en cubos pequeños.", "Escurre bien el atún enlatado hasta que esté seco y desmenuzado. A continuación, mezcla el atún en un bol con la cebolla y los huevos para formar una mezcla.", "Forma pequeñas hamburguesas redondas con la mezcla y fríelas en una sartén con un poco de aceite."], "image_url": "/images/recipes/42.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:43", "title": "Tazón de quinoa", "category": "Platos principales", "protein_g": 24, "carbs_g": 141, "fat_g": 9, "minutes": 30, "ingredients": ["150 g Quinoa", "100 g Brócoli", "150 g Tomates Cherry", "150 g Mango", "1 cdita Salsa de Soja", "Pimentón", "Sal"], "steps": ["Cocina la quinoa y el brócoli según las instrucciones del paquete.", "Mientras tanto, pela el mango y córtalo en cubos pequeños.", "A continuación, saltea brevemente la quinoa, el brócoli y el mango en una sartén con un poco de salsa de soja y sazónalos con sal y pimentón.", "Luego, coloca todo en un plato con los tomates cherry y disfruta."], "image_url": "/images/recipes/43.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:44", "title": "Tazón de quinoa con pollo", "category": "Platos principales", "protein_g": 66, "carbs_g": 103, "fat_g": 16, "minutes": 30, "ingredients": ["150 g Quinoa", "200 g Pollo", "0.5 Pimiento", "5 ml Aceite de Oliva", "Curry", "Sal"], "steps": ["Cocina la quinoa según las instrucciones del paquete.", "Mientras tanto, fríe el pollo con sal, curry y un poco de aceite en una sartén.", "Corta el pimiento en cubos pequeños.", "Por último, añade la quinoa y el pimiento al pollo en la sartén y fríe todo ligeramente."], "image_url": "/images/recipes/44.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:45", "title": "Helado de frambuesa", "category": "Snacks y meriendas", "protein_g": 34, "carbs_g": 28, "fat_g": 8, "minutes": 185, "ingredients": ["200 g Yogur de Soya", "150 ml Leche de Almendra (sin endulzar)", "2 Claras de Huevo", "160 g Frambuesas (congeladas)", "10 g Sirope de Agave", "20 g Proteína en Polvo (sabor Frambuesa)"], "steps": ["Separa los huevos y bate las claras en un bol con una batidora.", "Mezcla todos los ingredientes junto con las claras batidas en una batidora y mezcla hasta que se forme una mezcla ligeramente espesa.", "Introduce la mezcla en un molde de silicona para helado y congélala durante unas 3-4 horas."], "image_url": "/images/recipes/45.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:46", "title": "Bolsillos de tortita", "category": "Snacks y meriendas", "protein_g": 72, "carbs_g": 68, "fat_g": 7, "minutes": 30, "ingredients": ["3 Tortitas", "250 g Requesón Bajo en Grasa", "4 cda Agua", "30 g Proteína en Polvo (sabor Vainilla)", "200 g Fresas"], "steps": ["Prepara los tortitas según nuestra receta básica de tortitas.", "Combina la cuajada baja en grasa, la proteína en polvo y cuatro cucharadas de agua en un bol, y mezcla bien durante 1-2 minutos.", "Corta las fresas en rodajas y espárcelas junto con la cuajada baja en grasa sobre los tortitas, luego dóblalos en forma de bolsillos."], "image_url": "/images/recipes/46.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:47", "title": "Galletas de frambuesa", "category": "Snacks y meriendas", "protein_g": 39, "carbs_g": 41, "fat_g": 8, "minutes": 45, "ingredients": ["125 g Frambuesas", "50 g Avena", "40 g Proteína en Polvo (sabor Chocolate)"], "steps": ["Primero, precalienta el horno a 180 °C (350 °F).", "Mezcla la avena y la proteína en polvo en un bol con un poco de agua para formar una masa espesa. A continuación, añade las frambuesas a la masa.", "Dale forma de galletas del tamaño de la palma de la mano a la masa y distribúyelas en una bandeja de horno.", "Introduce la bandeja de horno con las galletas en el horno durante 18-20 minutos."], "image_url": "/images/recipes/47.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:48", "title": "Plátano crujiente", "category": "Snacks y meriendas", "protein_g": 3, "carbs_g": 51, "fat_g": 6, "minutes": 15, "ingredients": ["120 g Plátano", "6 g Aceite de Coco", "15 ml Sirope de Agave", "20 g Cornflakes"], "steps": ["Corta el plátano por la mitad a lo largo.", "Saltea ligeramente las mitades de plátano junto con los copos de maíz y el sirope de agave en una sartén con aceite de coco.", "Spread the cornflakes and agave syrup evenly over the banana slices."], "image_url": "/images/recipes/48.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:49", "title": "Arroz pegajoso con mango", "category": "Snacks y meriendas", "protein_g": 37, "carbs_g": 113, "fat_g": 5, "minutes": 30, "ingredients": ["100 g Arroz", "30 g Proteína en Polvo (sabor Coco)", "200 ml Leche de Coco", "Menta", "Eritritol", "0.5 Mango", "Gotas de Sabor"], "steps": ["Cocina el arroz glutinoso (disponible en tiendas de alimentación asiáticas) según las instrucciones del paquete.", "Después de cocinarlo, pasa el arroz a una sartén y añade eritritol (u otro sustituto del azúcar), leche de coco, proteína en polvo y gotas de sabor.", "Calienta la mezcla a fuego lento, removiendo constantemente, durante 2-3 minutos.", "Corta el mango en rodajas y sírvelo con el arroz en un plato."], "image_url": "/images/recipes/49.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:50", "title": "Brownies para volumen", "category": "Snacks y meriendas", "protein_g": 54, "carbs_g": 37, "fat_g": 40, "minutes": 25, "ingredients": ["120 g Plátano", "40 g Proteína en Polvo (sabor Chocolate)", "20 ml Leche", "30 g Cacao en Polvo", "60 g Mantequilla de Maní", "0.5 paquete Polvo de Hornear"], "steps": ["Combina el plátano, la proteína en polvo, el cacao en polvo, la mantequilla de cacahuete y la levadura en polvo en un bol con un chorrito de leche y mézclalo bien con una batidora.", "Extiende la masa uniformemente en una bandeja de horno y hornéala durante unos 12 minutos a 160 °C con aire circulante."], "image_url": "/images/recipes/50.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:51", "title": "Brownies de batata", "category": "Snacks y meriendas", "protein_g": 63, "carbs_g": 100, "fat_g": 30, "minutes": 30, "ingredients": ["120 g Plátano", "20 g Nueces", "150 g Batatas", "100 g Avena", "30 g Cacao en Polvo", "50 g Proteína en Polvo (sabor Chocolate)", "0.66 bolsa Paquete de Polvo de Hornear"], "steps": ["Cuece los dados de batata en un poco de agua durante unos 10 minutos hasta que estén blandos.", "Trocea el plátano y colócalo en un bol.", "Tritura los copos de avena en una batidora (o, como alternativa, utiliza 75 g de harina).", "Añade los boniatos cocidos, la avena, el cacao en polvo, la proteína en polvo y la levadura en polvo al plátano y mézclalo con una batidora para formar una masa.", "Pica las nueces en trozos pequeños con un cuchillo y amásalas uniformemente en la masa.", "Hornea durante aproximadamente 12 minutos a 160 °C (320 °F) con aire circulante."], "image_url": "/images/recipes/51.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:52", "title": "Brownies de carbohidratos", "category": "Snacks y meriendas", "protein_g": 31, "carbs_g": 106, "fat_g": 26, "minutes": 35, "ingredients": ["100 g Avena", "90 g Cacao en Polvo", "50 g Sirope de Agave", "70 g Eritritol", "2 Claras de Huevo"], "steps": ["Separa las claras de las yemas y bate las claras a punto de nieve.", "Tritura la avena en una batidora hasta que tenga una textura similar a la harina.", "Añade todos los ingredientes a un bol e incorpora suavemente las claras batidas.", "Hornea durante 15 minutos a 160 °C (320 °F) con circulación de aire."], "image_url": "/images/recipes/52.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:53", "title": "Cheesecake de arándanos", "category": "Snacks y meriendas", "protein_g": 144, "carbs_g": 167, "fat_g": 18, "minutes": 120, "ingredients": ["10 Dátiles", "45 g Harina de Coco", "2 Claras de Huevo", "0.5 cdita Polvo de Hornear", "20 g Sirope de Agave", "20 g Cacao en Polvo", "750 g Requesón Bajo en Grasa", "150 g Skyr (Arándano)", "2 cdita Jugo de Limón", "100 g Eritritol", "30 g Gelatina", "150 g Arándanos", "30 g Proteína en Polvo (sabor Vainilla)"], "steps": ["Separa los huevos y coloca solo las claras en un bol.", "Quítales el hueso a los dátiles y añádelos al bol junto con la harina de coco, la levadura en polvo, el sirope de agave y el cacao en polvo. Mezcla todo con una batidora.", "Extiende la masa en una bandeja de horno con un molde para hornear y aplánala. Hornea la base durante 15 minutos a 150 °C (300 °F). En un bol aparte, mezcla la cuajada baja en grasa, el skyr, el eritritol, el zumo de limón, la proteína en polvo y la gelatina en polvo con una batidora. Incorpora los arándanos a la masa con una cuchara.", "Spread the second layer evenly over the base in the baking form and bake for an additional 15 minutes at 340°F (170°C).", "Deja enfriar brevemente el pastel después de hornearlo y luego refrigéralo durante la noche."], "image_url": "/images/recipes/53.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:54", "title": "Receta de avena", "category": "Desayunos", "protein_g": 13, "carbs_g": 75, "fat_g": 7, "minutes": 5, "ingredients": ["100 g Avena", "500 ml Agua (o Leche)", "Sal", "20 g Miel"], "steps": ["Primero, hierve la avena con agua y sal.", "Luego, retira la olla del fuego y déjala enfriar durante 3 minutos.", "Por último, añade la miel."], "image_url": "/images/recipes/54.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:55", "title": "Muffins de avena y plátano", "category": "Desayunos", "protein_g": 34, "carbs_g": 150, "fat_g": 21, "minutes": 45, "ingredients": ["105 g Avena", "3 Plátanos", "2 Huevos", "50 g Miel", "1 cdita Polvo de Hornear", "3 g Bicarbonato de Sodio", "Sal", "50 ml Bebida de Almendra", "Canela"], "steps": ["Llena media taza con avena. Pon el resto en un procesador de alimentos y procésalo hasta obtener harina de avena.", "A continuación, tritura el plátano con un tenedor.", "Mezcla la harina de avena, el plátano triturado, los huevos, la miel, la bebida de almendras, la levadura en polvo y el bicarbonato sódico, y sazónalo con sal y canela.", "Incorpora la avena restante y rellena un molde para muffins con la masa.", "Hornea el molde durante 20 minutos a 175 °C (350 °F)."], "image_url": "/images/recipes/55.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:56", "title": "Ensalada de quinoa con pesto", "category": "Platos principales", "protein_g": 26, "carbs_g": 88, "fat_g": 12, "minutes": 35, "ingredients": ["75 g Quinoa", "200 g Garbanzos", "75 g Tomates Cherry", "40 g Cebolla (roja)", "30 g Cebolla de Verdeo", "40 g Rúcula", "0.5 cda Vinagre de Manzana", "0.5 cdita Pesto (Rosso)", "Sal y Pimienta"], "steps": ["Primero, cocina la quinoa según las instrucciones del paquete.", "Mientras tanto, escurre los garbanzos, corta los tomates cherry por la mitad y pica finamente la cebolla y la cebolleta.", "Trocea la rúcula en trozos pequeños y mézclala con el resto.", "Cuando la quinoa se haya enfriado un poco, añádela también a la mezcla."], "image_url": "/images/recipes/56.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:57", "title": "Pizza de espinaca y tomate cherry", "category": "Platos principales", "protein_g": 30, "carbs_g": 157, "fat_g": 20, "minutes": 60, "ingredients": ["200 g Harina de Trigo", "100 ml Agua", "4 g Levadura", "2 cda Aceite de Oliva", "Pimienta", "Sal", "100 g Tomates Cherry", "125 g Tomates (colados)", "3 g Ajo", "40 g Cebolla", "Orégano", "150 g Espinacas", "20 g Queso Parmesano (vegano)"], "steps": ["Mezcla la harina de trigo, el agua, la levadura, el aceite de oliva y una pizca de sal en un bol para formar una masa, luego cúbrela y déjala reposar en un lugar cálido durante 30 minutos.", "Mientras tanto, corta los tomates cherry por la mitad y resérvalos.", "Sazona los tomates colados con orégano, pimienta y sal, y resérvalos.", "Pica finamente el ajo y la cebolla y saltéalos en una sartén con una cucharada de aceite de oliva. Añade las espinacas a la sartén y caliéntalas brevemente.", "Después de 30 minutos, extiende la masa finamente en una bandeja para hornear y esparce la salsa de tomate uniformemente por encima.", "Distribuye las espinacas, los tomates y el queso parmesano vegano en la pizza y hornea durante 15-20 minutos a 390 °F (200 °C) en un horno precalentado."], "image_url": "/images/recipes/57.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:58", "title": "Ensalada de quinoa, aguacate y garbanzos", "category": "Platos principales", "protein_g": 27, "carbs_g": 69, "fat_g": 26, "minutes": 45, "ingredients": ["50 g Quinoa", "1 cdita Aceite de Oliva", "Pimienta", "Sal", "Pimentón", "40 g Lechuga de Cordero", "0.5 g Aguacate", "200 g Garbanzos", "Orégano"], "steps": ["Primero, cocina la quinoa según las instrucciones del paquete.", "Mientras tanto, escurre los garbanzos y colócalos en un bol.", "Añade una cucharadita de aceite de oliva, pimienta, sal, pimentón y orégano a los garbanzos y mezcla bien.", "Spread everything on a baking sheet and bake for about 20 minutes at 430°F (220°C) in the oven.", "After that, wash the lamb's lettuce and arrange it on a plate with the cooked quinoa, seasoning to taste.", "Finally, remove the chickpeas from the oven and serve with the avocado."], "image_url": "/images/recipes/58.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:59", "title": "Pad Thai", "category": "Platos principales", "protein_g": 39, "carbs_g": 119, "fat_g": 49, "minutes": 60, "ingredients": ["200 g Fideos de Arroz", "340 g Brócoli", "300 g Zanahorias", "20 g Cebolla de Verdeo", "4 cda Salsa de Soja", "2 cda Jugo de Lima", "60 g Mantequilla de Maní", "2 cda Sirope de Arce", "1 cdita Jengibre (rallado)", "1 cda Salsa de Pescado (vegana)", "2 cda Aceite de Sésamo", "100 g Brotes de Soya", "10 g Cilantro (fresco)", "65 g Cacahuetes", "70 g Huevo", "Copos de Chile (si lo deseas)"], "steps": ["Empieza por cocinar los fideos de arroz según las instrucciones del paquete.", "Mientras tanto, separa el brócoli en ramilletes, pela las zanahorias y córtalas en tiras con un pelador de verduras.", "Llena una olla pequeña con el brócoli, añade agua hasta la mitad y cocina durante unos 10 minutos a fuego medio con la tapa medio cerrada.", "Al mismo tiempo, corta la cebolleta en aros y mezcla la salsa de soja, el zumo de lima, la mantequilla de cacahuete, el sirope de arce, el jengibre y la salsa de pescado vegana. Añade agua según sea necesario para alcanzar la consistencia deseada.", "Ahora escurre el brócoli, calienta la mitad del aceite de sésamo en una sartén y saltea el brócoli durante unos 3 minutos a fuego medio.", "Añade las tiras de zanahoria, los aros de cebolleta y los brotes de soja, y sofríe durante otros 2 minutos.", "Mientras tanto, pica el cilantro y los cacahuetes.", "Añade el huevo a la sartén y mézclalo bien con las verduras. Deja que se cocine durante otros 2 minutos.", "Escurre los fideos de arroz y mézclalos con el aceite de sésamo restante para que queden suaves y evitar que se peguen entre sí.", "Vierte la mitad de la salsa sobre los fideos y mézclalos bien.", "Añade la otra mitad de la salsa junto con el cilantro a las verduras en la sartén y mezcla bien.", "Reparte los fideos de arroz en los platos y decora con las verduras, los cacahuetes picados y las hojuelas de chile."], "image_url": "/images/recipes/59.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:60", "title": "Macarrones con queso veganos", "category": "Platos principales", "protein_g": 39, "carbs_g": 170, "fat_g": 38, "minutes": 45, "ingredients": ["0.5 Patata", "35 g Zanahoria", "3 g Ajo", "200 g Pasta de Macarrones", "70 g Pasta de Anacardos", "30 ml Bebida de Almendra", "1 cdita Jugo de Limón", "Pimentón", "Pimienta", "Sal", "Perejil (fresco)"], "steps": ["Primero, pela la patata y la zanahoria y córtalas en trozos grandes.", "Coloca las verduras en una olla pequeña con agua y déjalas hervir a fuego lento durante 20 minutos.", "Mientras tanto, pela el diente de ajo.", "Una vez que las verduras estén cocidas, escúrrelas y cocina la pasta al dente.", "Ahora prepara la salsa. Añade la pasta de anacardos, la bebida de almendras, el diente de ajo, el zumo de limón, el pimentón, la pimienta, la sal y los cubitos de verduras en un bol.", "Utiliza una batidora de mano para mezclar los ingredientes y obtener una salsa cremosa.", "Por último, escurre la pasta y sírvela con la salsa."], "image_url": "/images/recipes/60.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:61", "title": "Barra de masa para galletas vegana", "category": "Snacks y meriendas", "protein_g": 120, "carbs_g": 120, "fat_g": 70, "minutes": 15, "ingredients": ["100 g Avena", "100 g Proteína en Polvo (sabor Vainilla)", "150 ml Leche de Soya", "50 g Aceite de Coco", "50 g Trozos de Chocolate (vegano)"], "steps": ["Primero, procesa la avena hasta convertirla en harina con una batidora.", "Añade la proteína en polvo y la leche de soja, y mezcla bien. Añade más leche de soja o proteína en polvo si la masa está demasiado dura o líquida.", "A continuación, añade el aceite de coco, mezcla todo hasta obtener una masa suave e incorpora los trozos de chocolate.", "Prepara una bandeja de horno con papel de hornear y presiona la masa hasta darle la forma deseada.", "Deja reposar la masa en el frigorífico durante 10-15 minutos y, a continuación, córtala en barras del mismo tamaño."], "image_url": "/images/recipes/61.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:62", "title": "Curry de lentejas y coco", "category": "Platos principales", "protein_g": 57, "carbs_g": 124, "fat_g": 23, "minutes": 30, "ingredients": ["80 g Cebolla", "230 g Calabacín", "1 cdita Aceite de Oliva", "1 Ajo", "0.5 Chile", "Comino (molido)", "Sal y Pimienta (al gusto)", "280 ml Agua", "200 g Lentejas Rojas", "200 ml Leche de Coco (reducida en grasa)", "Cilantro (fresco)", "1 cdita Cúrcuma (molida)"], "steps": ["Pica el calabacín y la cebolla y saltéalos en una olla grande con una cucharadita de aceite de oliva.", "Pica finamente el chile, presiona el diente de ajo y añádelos a la olla junto con el comino, la cúrcuma, la pimienta y la sal. Continúa salteando durante 2 minutos.", "Añade el agua poco a poco y luego incorpora las lentejas rojas y la leche de coco. Deja que todo se cocine a fuego lento durante 15 minutos.", "Por último, sazona con pimienta y sal, y decora con cilantro fresco."], "image_url": "/images/recipes/62.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:63", "title": "Lasaña vegana de tofu", "category": "Platos principales", "protein_g": 45, "carbs_g": 143, "fat_g": 38, "minutes": 90, "ingredients": ["40 g Cebolla", "1 g Ajo", "0.5 cdita Aceite de Oliva", "100 g Tofu", "1 cda Pasta de Tomate", "1 cda Margarina", "1.5 cda Harina", "Nuez Moscada (molida)", "Sal y Pimienta", "125 g Lasaña (sin Huevo)", "63 g Queso Rallado (vegano)", "250 g Tomate (en trozos)", "250 ml Bebida de Soya", "Orégano (rallado)"], "steps": ["Corta los dientes de ajo y la cebolla en dados y saltéalos en una sartén con aceite.", "Seca el tofu, desmóldalo en la sartén y saltéalo.", "Añade la pasta de tomate, mézclalo y desglasa con los tomates en trozos. Deja que hierva a fuego lento durante unos 15 minutos.", "Pon la margarina en una olla y derrítela. A continuación, añade la harina y remueve brevemente mientras se fríe.", "Vierte poco a poco la bebida de soja y remueve a fuego medio durante unos 7-10 minutos, hasta que la salsa espese. Ahora sazona con nuez moscada, pimienta y sal.", "Spread two tablespoons of the white sauce on the bottom of the baking dish and layer the first set of lasagna noodles.", "Layer the white sauce, the bolognese, and the lasagna noodles alternately, with the final layer being the white sauce.", "Lastly, sprinkle the casserole with shredded cheese and drizzle some oregano. Luego hornea a 220 °C (430 °F) durante 45 minutos hasta que esté dorado."], "image_url": "/images/recipes/63.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:64", "title": "Chili sin carne", "category": "Platos principales", "protein_g": 42, "carbs_g": 117, "fat_g": 29, "minutes": 45, "ingredients": ["40 g Cebolla", "0.5 cda Aceite de Oliva", "75 g Quinoa", "175 ml Caldo de Verduras", "250 g Frijoles Rojos (enlatados)", "143 g Maíz (enlatado)", "1.5 cda Pasta de Tomate", "Sal y Pimienta", "Pimentón", "Cilantro", "0.125 Pimiento (rojo)", "20 ml Jugo de Lima", "0.5 g Aguacate", "200 g Tomates (en trozos)"], "steps": ["Pica finamente la cebolla y saltéala en una sartén grande con aceite de oliva.", "Enjuaga brevemente la quinoa en un colador con agua.", "Agrega la quinoa a la sartén y saltéala durante 3 minutos.", "Desglasar la mezcla con caldo de verduras y añadir las alubias rojas, el maíz, los tomates cortados en dados y la pasta de tomate. Dejar que hierva a fuego lento durante unos 30 minutos. Añadir sal, pimienta, pimentón y cilantro y remover bien. Por último, cortar el pimiento y el aguacate en dados y decorar el chile terminado con el zumo de lima."], "image_url": "/images/recipes/64.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:65", "title": "Gofres veganos de limón", "category": "Snacks y meriendas", "protein_g": 15, "carbs_g": 121, "fat_g": 20, "minutes": 35, "ingredients": ["100 g Harina de Trigo", "25 g Harina Integral", "8 g Polvo de Hornear", "1 Limones (orgánicos)", "175 ml Bebida de Almendra (sin endulzar)", "2 cda Sirope de Arce", "15 ml Aceite de Canola"], "steps": ["Primero, mezcla la harina integral, la harina de trigo y la levadura en polvo.", "Ralla y exprime los limones, y añádelos a la mezcla de harina junto con el sirope de arce y la bebida de almendras.", "Utiliza un aparato de cocina para mezclar todo hasta obtener una masa cremosa.", "Precalienta la plancha para gofres y úntala con un poco de aceite antes de cada gofre."], "image_url": "/images/recipes/65.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:66", "title": "Albóndigas veganas con puré de patatas", "category": "Platos principales", "protein_g": 58, "carbs_g": 169, "fat_g": 37, "minutes": 80, "ingredients": ["400 g Patatas", "Sal y Pimienta", "250 g Frijoles Rojos (enlatados)", "3 Ajo", "0.5 Cebolla", "35 g Semillas de Girasol", "45 g Avena", "120 g Pasta de Tomate", "20 g Linaza (molida)", "Comino (molido)", "Pimentón", "80 ml Crema de Soya", "360 ml Caldo de Verduras", "Curry", "Jengibre (molido)", "1 cda Almidón de Maíz", "Perejil (fresco)", "80 ml Bebida de Avena", "Nuez Moscada (molida)"], "steps": ["Precalienta el horno a 180 °C.", "Primero, pela y corta las patatas por la mitad, luego colócalas en una olla. Cubre las patatas completamente con agua.", "Añade un poco de sal a las patatas y cocina a fuego lento con la tapa puesta durante unos 20 minutos a fuego medio.", "Mientras tanto, pela la cebolla y los dientes de ajo, y escurre y enjuaga las alubias en un colador.", "Pica la cebolla y dos tercios del ajo y mézclalos con la avena, las semillas de girasol, las alubias, las semillas de lino, la mitad de la pasta de tomate, el pimentón, el comino, la pimienta y la sal. Tritura la mezcla hasta obtener una pasta suave con una batidora de mano. Con las manos húmedas, forma pequeñas bolas con la masa, colócalas en una bandeja de horno forrada con papel de horno y hornéalas en la rejilla central durante unos 20 minutos. Mientras tanto, bate la pasta de tomate restante con la nata de soja en una sartén. Añade poco a poco el caldo de verduras y mezcla para crear una salsa cremosa. Sazona la salsa con jengibre, curry en polvo, sal y pimienta. Añade el diente de ajo restante y cocina a fuego medio durante unos 10 minutos.", "Mezcla la maicena con dos cucharadas de agua fría, añádela a la salsa y calienta brevemente.", "Pica el perejil y añádelo a la salsa. Mantén las albóndigas calientes en la salsa.", "Escurre las patatas cocidas y tritúralas con leche de avena, nuez moscada y sal con una batidora de mano hasta que queden cremosas.", "Reparte el puré de patatas terminado en platos y sírvelo con las albóndigas veganas y la salsa."], "image_url": "/images/recipes/66.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:67", "title": "Sándwich de ensalada de huevo vegano", "category": "Platos principales", "protein_g": 44, "carbs_g": 69, "fat_g": 22, "minutes": 5, "ingredients": ["140 g Tofu Natural", "150 g Tofu de Seda", "1 cda Mayonesa (vegana)", "1 cda Levadura Nutricional", "0.5 cdita Cúrcuma (molida)", "Sal y Pimienta", "160 g Pan Integral", "2 cda Berro"], "steps": ["Primero, seca el tofu sedoso y el tofu natural.", "En un bol, mezcla el tofu sedoso, el tofu natural, las escamas de levadura, la mayonesa y la cúrcuma con un tenedor hasta obtener una mezcla suave. Sazona con sal y pimienta al gusto.", "Por último, unta la ensalada de huevo vegana en el pan y decora con berro."], "image_url": "/images/recipes/67.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:68", "title": "Pizza de desayuno con bayas", "category": "Desayunos", "protein_g": 29, "carbs_g": 131, "fat_g": 16, "minutes": 30, "ingredients": ["150 g Avena", "15 g Semillas de Chía", "225 g Puré de Manzana", "150 ml Yogur de Soya", "150 g Bayas (congeladas)"], "steps": ["Tritura la avena hasta convertirla en un polvo fino con una batidora.", "Deja las semillas de chía en remojo en media taza de agua durante un rato.", "Mezcla bien las semillas de chía y la avena con la compota de manzana.", "A continuación, extiende la masa en una bandeja de horno forrada con papel de horno y hornéala a 175 °C (350 °F) durante 20 minutos.", "Mientras tanto, deja que las bayas se descongelen y haz un puré con la mitad de ellas y el yogur.", "Después de hornear, extiende la mezcla de yogur y bayas sobre la masa de pizza con una cuchara. Distribuye la otra mitad de las bayas sobre la pizza.", "Por último, corta en trozos con un cuchillo y sirve."], "image_url": "/images/recipes/68.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:69", "title": "Batido todo incluido", "category": "Snacks y meriendas", "protein_g": 38, "carbs_g": 110, "fat_g": 6, "minutes": 2, "ingredients": ["1 Plátano", "1 Manzana", "1 Kiwi", "100 g Bayas (congeladas)", "50 g Copos de 5 Granos", "25 g Proteína en Polvo (sabor Vainilla)", "250 ml Bebida de Almendra", "Canela"], "steps": ["Pica las frutas en trozos más pequeños y colócalas en una batidora.", "Añade todos los demás ingredientes.", "Mezcla a máxima velocidad durante unos 20-30 segundos.", "Sirve en una coctelera o vaso. Opcionalmente, espolvorea un poco de canela o cacao en polvo por encima para decorar."], "image_url": "/images/recipes/69.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:70", "title": "Yogur de arándanos", "category": "Snacks y meriendas", "protein_g": 21, "carbs_g": 24, "fat_g": 18, "minutes": 5, "ingredients": ["20 g Almendras (picadas)", "400 g Yogur de Soya", "15 g Hojas de Menta (frescas)", "Edulcorante", "250 g Arándanos", "5 g Semillas de Chía"], "steps": ["Tuesta las almendras en una sartén durante un rato y reserva unas cuantas para decorar.", "Añade los arándanos a la sartén y caliéntalos brevemente. Mézclalas con las almendras y añádelas al yogur de soja.", "Pica finamente las hojas de menta y mézclalas con el yogur.", "Por último, endulza al gusto con un edulcorante de tu elección y sirve con las almendras y las semillas de chía restantes."], "image_url": "/images/recipes/70.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:71", "title": "Tostada con huevos revueltos veganos", "category": "Desayunos", "protein_g": 57, "carbs_g": 43, "fat_g": 41, "minutes": 15, "ingredients": ["300 g Tofu Natural", "1.5 Chalotas", "1.5 cda Aceite de Oliva", "Sal y Pimienta", "Pimentón", "90 g Yogur de Soya", "75 g Pan Integral", "Cúrcuma (molida)", "8 g Cebollino (fresco)"], "steps": ["Aprieta suavemente el tofu natural con las manos y desmígalo en trozos lo más pequeños posible.", "A continuación, pica finamente las chalotas y saltéalas brevemente en la sartén con aceite de oliva.", "Añade el tofu natural a la sartén, fríelo ligeramente durante unos 5-7 minutos y sazónalo con sal, pimienta, pimentón y cúrcuma.", "Incorpora el yogur de soja y caliéntalo durante unos minutos en la sartén.", "Pon las tostadas en una tostadora y sírvelas con el revuelto de tofu y un poco de cebollino."], "image_url": "/images/recipes/71.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:72", "title": "Barrita de granola con plátano y cacahuate", "category": "Snacks y meriendas", "protein_g": 41, "carbs_g": 193, "fat_g": 34, "minutes": 20, "ingredients": ["200 g Avena", "100 ml Bebida de Almendra (sin endulzar)", "40 g Mantequilla de Maní", "1 cdita Sirope de Arce", "300 g Plátanos (maduros)"], "steps": ["Precalienta el horno a 160 °C (320 °F).", "Pela los plátanos y tritúralos con un tenedor.", "Combina el puré de plátano con todos los demás ingredientes y vierte la mezcla en una fuente para horno forrada con papel de hornear.", "Hornea en la rejilla del medio durante unos 15 minutos.", "Por último, deja enfriar la mezcla y córtala en barritas."], "image_url": "/images/recipes/72.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:73", "title": "Sloppy Joes veganos de lentejas", "category": "Platos principales", "protein_g": 39, "carbs_g": 120, "fat_g": 12, "minutes": 35, "ingredients": ["100 g Lentejas (verdes)", "100 ml Caldo de Verduras", "100 ml Agua", "1 Cebolla", "1 Ajo", "0.25 Pimiento (rojo)", "1 Aceite de Oliva", "200 g Tomates (colados)", "Sal y Pimienta", "Chile en Polvo", "Pimentón (dulce)", "130 g Pan Integral", "Comino (molido)"], "steps": ["Pon a hervir las lentejas, el caldo de verduras y el agua en una olla. Reduce el fuego y deja que hierva a fuego lento durante unos 20 minutos, removiendo de vez en cuando.", "Corta la cebolla en aros, reserva unos cuantos y corta el resto en dados, junto con el pimiento.", "Añade la cebolla y los dados de pimiento a una sartén precalentada con aceite de oliva, presiona el ajo y cocina durante unos 4 minutos.", "Añade los tomates colados, la sal, la pimienta, el pimentón, el chile en polvo y el comino, y mezcla todo junto.", "Añade las lentejas cocidas, deja que todo hierva a fuego lento durante unos 5 minutos y remueve con regularidad.", "Por último, corta los panecillos de trigo, unta la mezcla de la sartén en las mitades inferiores de los panecillos, decora con los aros de cebolla y cúbrelos con las mitades superiores de los panecillos."], "image_url": "/images/recipes/73.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:74", "title": "Tazón de tofu y garbanzos", "category": "Platos principales", "protein_g": 36, "carbs_g": 104, "fat_g": 30, "minutes": 50, "ingredients": ["100 g Arroz Integral", "100 g Tofu Natural", "0.25 Ajo", "1 cda Aceite de Sésamo", "1 cda Salsa de Soja", "1 cda Sirope de Arce", "Copos de Chile", "0.5 cda Jugo de Lima", "15 g Mantequilla de Maní", "85 g Brócoli", "50 g Garbanzos (enlatados)", "Sal y Pimienta", "75 g Zanahoria", "8 g Espinaca Baby"], "steps": ["Precalienta el horno a 180 °C.", "Cocina el arroz integral según las instrucciones del paquete.", "Seca el tofu natural con un paño de cocina y córtalo en dados.", "Presiona el diente de ajo en un bol y mézclalo con la mitad del aceite de sésamo, la salsa de soja, el sirope de arce, las hojuelas de chile, el jugo de lima y la mantequilla de maní.", "Combina los cubos de tofu con la mitad de la salsa y colócalos en una fuente para hornear.", "Escurre los garbanzos, separa el brócoli en floretes, mezcla ambos con el aceite de sésamo restante, sazona con sal y pimienta y colócalos en una segunda fuente de horno.", "Pon ambas fuentes en el horno durante unos 20 minutos.", "Mientras tanto, corta la zanahoria en tiras finas con un cuchillo.", "Divide el arroz integral cocido en cuencos y sírvelo con el tofu, el brócoli, los garbanzos, las espinacas, la zanahoria y la salsa restante."], "image_url": "/images/recipes/74.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:75", "title": "Arroz en una olla con frijoles rojos", "category": "Platos principales", "protein_g": 53, "carbs_g": 191, "fat_g": 6, "minutes": 35, "ingredients": ["125 g Arroz", "188 ml Agua", "0.5 Pimiento (rojo)", "1 Pimiento (amarillo)", "143 g Maíz (enlatado)", "360 g Frijoles rojos (enlatados)", "410 g Tomates (en trozos)", "1 Ajo", "Sal y Pimienta", "Pimentón (dulce)", "Orégano"], "steps": ["Primero, cocina el agua y el arroz en una olla grande a fuego medio.", "Mientras tanto, quita las semillas del pimiento y córtalo en trozos pequeños.", "Escurre las alubias y el maíz.", "Añade las alubias, el maíz, el pimiento y los tomates cortados en dados al arroz y mezcla todo bien.", "Aplasta los dientes de ajo en la olla, añade las especias y deja que todo hierva a fuego lento durante unos 25 minutos, removiendo regularmente."], "image_url": "/images/recipes/75.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:76", "title": "Fideos de arroz con edamame", "category": "Platos principales", "protein_g": 27, "carbs_g": 163, "fat_g": 16, "minutes": 35, "ingredients": ["150 g Pasta de Arroz", "150 g Zanahorias", "100 g Kale", "0.5 Ajo", "0.5 cdita Jengibre (rallado)", "10 g Pasta de Miso", "1.5 cdita Tamari", "1 cdita Sirope de Arce", "1 cdita Jugo de Lima", "10 g Sriracha", "1 cdita Aceite de Sésamo", "100 g Edamame (cocido)", "5 g Semillas de Sésamo"], "steps": ["Primero, cocina la pasta de arroz según las instrucciones del paquete, escúrrela y enjuágala con agua fría.", "Pela las zanahorias y córtalas en tiras finas con un cuchillo. Limpia también la col rizada, quítale el tallo y córtala también en tiras finas.", "Pica finamente el ajo y mézclalo en un bol con pasta de miso, jengibre, sirope de arce, tamari, zumo de lima, salsa Sriracha y la mitad del aceite de sésamo.", "Calienta el aceite de sésamo restante en una sartén a fuego medio y saltea la pasta de arroz con la col rizada, las judías edamame, las zanahorias y el aderezo durante 3 minutos, hasta que la col rizada se ablande.", "Por último, sirve el plato en platos y decora con semillas de sésamo."], "image_url": "/images/recipes/76.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:77", "title": "Tazón de lentejas y patata", "category": "Platos principales", "protein_g": 37, "carbs_g": 114, "fat_g": 23, "minutes": 50, "ingredients": ["300 g Patatas", "Sal y Pimienta", "1.5 Chalota", "1 Ajo", "8 g Jengibre (fresco)", "1.5 cda Aceite de Oliva", "130 g Lentejas (rojas)", "0.5 cdita Garam Masala"], "steps": ["Primero, pela las patatas, córtalas en cubos pequeños y cocínalas en una olla con agua y un poco de sal durante unos 10 minutos. Deberían estar todavía un poco firmes.", "Mientras tanto, pela el ajo, la chalota y el jengibre y córtalos en cubos pequeños.", "Calienta la mitad del aceite de oliva en una olla y saltea las chalotas, el ajo y el jengibre durante unos 3 minutos.", "A continuación, añade las lentejas y el garam masala, vierte agua (hasta que todo quede cubierto), deja que hierva a fuego lento durante unos 15 minutos, removiendo de vez en cuando, y añade más agua si es necesario.", "Escurre las patatas cocidas y fríelas en una sartén con el aceite de oliva restante durante unos 8 minutos hasta que estén crujientes.", "Por último, coloca las patatas y las lentejas en cuencos."], "image_url": "/images/recipes/77.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:78", "title": "Wrap de falafel", "category": "Platos principales", "protein_g": 22, "carbs_g": 62, "fat_g": 64, "minutes": 30, "ingredients": ["1 taza Queso Crema Vegano", "1 cdita Mostaza", "1 manojo Cilantro (fresco)", "1 pizca Pimienta", "0.5 cdita Curry", "1 Cebolla", "200 g Tomates Cherry", "1 Aguacate", "1 paquete Falafel", "4 cda Aceite de Oliva", "2 Tortilla de Harina de Trigo", "100 g Lechuga"], "steps": ["Combina queso crema vegano con cilantro picado, mostaza, curry en polvo y pimienta. Quita el hueso del aguacate y córtalo en gajos. Lava los tomates cherry y córtalos por la mitad. Pela la cebolla y córtala en rodajas finas.", "Prepara el falafel según las instrucciones del paquete y fríelo en aceite de oliva. Al final, añade brevemente las cebollas y los tomates a la sartén.", "Tuesta la tortilla de harina de trigo en una sartén, extiende la crema sobre ellas y distribuye el aguacate y la lechuga por encima.", "Finalmente, coloca el falafel con las cebollas y los tomates en el centro de las tortillas y enrollalas."], "image_url": "/images/recipes/78.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:79", "title": "Salteado de tofu y champiñones", "category": "Platos principales", "protein_g": 85, "carbs_g": 36, "fat_g": 52, "minutes": 25, "ingredients": ["2 Ajo", "400 g Tofu Natural", "2 cda Aceite de Oliva", "2 Puerros", "250 g Champiñones", "250 ml Caldo de Verduras", "1 cdita Almidón de Maíz", "Sal y Pimienta", "0.25 Limón (orgánico)", "2 cda Salsa de Soja"], "steps": ["Primero, pica finamente los dientes de ajo.", "Exprime suavemente el tofu natural y córtalo en cubos.", "Ralla un poco de cáscara de limón y, junto con el ajo y el tofu, fríelo en una sartén con una cucharada de aceite durante unos 7-8 minutos.", "Limpia los champiñones y los puerros y córtalos en rodajas finas.", "Una vez que los cubos de tofu tengan un color dorado claro, retíralos de la sartén y reserva.", "Con el aceite restante, saltea los puerros durante 5 minutos, luego añade los champiñones y cocina durante otros 5-7 minutos.", "Mientras tanto, combina el caldo de verduras con la salsa de soja y la maicena, y finalmente añade los cubos de tofu de nuevo a la sartén y lleva a ebullición.", "Sazona con sal y pimienta al gusto y sirve en cuencos."], "image_url": "/images/recipes/79.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:80", "title": "Batido proteico de cacahuate", "category": "Snacks y meriendas", "protein_g": 30, "carbs_g": 38, "fat_g": 13, "minutes": 5, "ingredients": ["20 g Mantequilla de Maní", "150 g Plátano (maduro)", "30 g Proteína en Polvo (sabor Chocolate)", "150 ml Bebida de Almendra (sin endulzar)", "Canela"], "steps": ["Coloca la mantequilla de cacahuete, la bebida de almendras, el polvo de proteínas, el plátano y la canela en una licuadora y mezcla durante 30-60 segundos (dependiendo de la potencia de la licuadora). Si el batido está demasiado espeso, añade más bebida de almendras o agua a tu gusto.", "Vierte en un vaso y disfruta."], "image_url": "/images/recipes/80.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:81", "title": "Pudín proteico de vainilla", "category": "Snacks y meriendas", "protein_g": 32, "carbs_g": 36, "fat_g": 2, "minutes": 5, "ingredients": ["40 g Polvo de Pudín (sabor Vainilla)", "40 g Proteína en Polvo (sabor Vainilla)", "400 ml Agua", "Gotas de Sabor de Vainilla"], "steps": ["Mezcla el polvo de pudín, el polvo de proteínas y el agua en un recipiente.", "Calienta la mezcla en el microondas a máxima potencia durante 30 segundos, luego remueve bien.", "Repite el paso anterior unas 3-5 veces hasta que el pudín alcance la consistencia deseada.", "Si lo deseas, mejora el sabor con unas gotas de aroma de vainilla."], "image_url": "/images/recipes/81.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:82", "title": "Pasta con salmón", "category": "Platos principales", "protein_g": 37, "carbs_g": 77, "fat_g": 27, "minutes": 20, "ingredients": ["100 g Filete de Salmón", "100 g Pasta (Integral)", "50 g Queso Crema Bajo en Grasa con Hierbas", "0.25 Ajo", "0.25 Limón", "0.5 cda Aceite Vegetal", "Eneldo"], "steps": ["Cocina la pasta según las instrucciones del paquete y calienta una sartén a fuego medio.", "Corta el filete de salmón en cubos y pica o prensa el ajo.", "Fríe ambos con un poco de aceite en la sartén caliente durante unos 5 minutos.", "Añade el queso crema de hierbas bajo en grasa y la pasta cocida junto con un poco de agua de la pasta.", "Remueve todo junto y sazona la salsa con sal, pimienta, zumo de limón y eneldo."], "image_url": "/images/recipes/82.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:83", "title": "Avena de vainilla y coco", "category": "Desayunos", "protein_g": 47, "carbs_g": 103, "fat_g": 28, "minutes": 10, "ingredients": ["250 ml Leche de Coco", "150 g Avena", "50 g Cerezas", "30 g Proteína en Polvo", "Vainilla"], "steps": ["Calienta brevemente la leche de coco en una olla hasta que hierva.", "Añade la avena y remueve regularmente.", "Una vez que la leche haya sido absorbida por la avena, añade el polvo de proteínas y las cerezas.", "Remueve bien una última vez y sirve en un recipiente."], "image_url": "/images/recipes/83.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:84", "title": "Panecillos de batata", "category": "Desayunos", "protein_g": 37, "carbs_g": 97, "fat_g": 29, "minutes": 30, "ingredients": ["120 g Batatas", "1 cdita Canela", "90 g Harina de Espelta", "30 g Proteína en Polvo (sabor Vainilla)", "25 g Grasa de Coco", "10 g Pasas", "0.5 cdita Polvo de Hornear"], "steps": ["Primero, cocina las batatas en una olla con agua hasta que estén blandas.", "Mientras tanto, derrite la grasa de coco en el microondas o en una sartén y engrasa un recipiente con ella.", "Mezcla las batatas con todos los demás ingredientes en el recipiente engrasado y amasa hasta formar una masa.", "Forma pequeños rollos con la masa y colócalos en una bandeja de horno.", "Hornea los rollos a 160°C durante 15-20 minutos hasta que estén dorados."], "image_url": "/images/recipes/84.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:85", "title": "Tortilla de salmón", "category": "Desayunos", "protein_g": 58, "carbs_g": 20, "fat_g": 38, "minutes": 10, "ingredients": ["3 Huevos", "50 ml Leche", "100 g Pepino", "1 cda Aceite de Oliva", "100 g Requesón con Hierbas (light)", "100 g Salmón", "100 g Zanahorias", "1 cda Harina de Espelta", "Sal y Pimienta", "Curry"], "steps": ["Añade huevos, leche, harina de espelta, curry en polvo, sal y pimienta a un recipiente y mezcla bien. Luego, corta el pepino y las zanahorias y cuartéalos.", "Calienta el aceite de oliva en una sartén grande, vierte la mezcla de huevo y cocina durante unos 2 minutos a fuego medio.", "Extiende el salmón, el requesón de hierbas bajo en grasa, las zanahorias y el pepino por encima y cocina la tortilla, tapada, durante unos 4 minutos a fuego lento.", "Finalmente, dobla la tortilla y sirve."], "image_url": "/images/recipes/85.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:86", "title": "Sándwich de atún", "category": "Desayunos", "protein_g": 43, "carbs_g": 31, "fat_g": 11, "minutes": 5, "ingredients": ["30 g Queso Crema (granulado)", "30 g Yogur", "20 g Crema de Ensalada (light)", "0.25 Manzana", "30 g Rábano", "25 g Cebolla", "10 g Nuez", "1 Lechuga", "1 Pan Integral", "150 g Atún"], "steps": ["Corta la manzana y la cebolla en dados con un cuchillo.", "Escurre el líquido del atún.", "En un recipiente, mezcla el atún, la manzana, la cebolla, el queso crema, el yogur y la crema de ensalada, y luego extiéndelo sobre una rebanada de pan.", "Cubre con lechuga, nueces y rábanos, y tapa con otra rebanada de pan."], "image_url": "/images/recipes/86.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:87", "title": "Huevos revueltos con jamón y queso", "category": "Desayunos", "protein_g": 41, "carbs_g": 6, "fat_g": 33, "minutes": 10, "ingredients": ["3 Huevos", "2 Jamón Crudo", "50 g Queso Rallado (light)", "40 g Cebolla", "1 cda Aceite de Oliva", "Sal y Pimienta", "Cebollino"], "steps": ["Primero, corta la cebolla en dados y saltéala en una sartén con el aceite de oliva.", "Mientras tanto, corta el jamón en cuadrados pequeños, añádelo a la sartén y saltéalo también.", "Rompe los huevos en un recipiente o taza, bátelos y viértelos en la sartén.", "Añade el queso para untar y las cebolletas picadas, y sazona la mezcla con sal y pimienta."], "image_url": "/images/recipes/87.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:88", "title": "Bagel con atún y huevo", "category": "Desayunos", "protein_g": 28, "carbs_g": 52, "fat_g": 8, "minutes": 5, "ingredients": ["1 Bagel", "1 Huevo", "1 Tomate", "50 g Atún", "1 cda Crema de Ensalada (light)", "1 Lechuga de Cordero", "1 cda Aceite de Oliva", "Sal y Pimienta"], "steps": ["Primero, rompe el huevo en una sartén y fríelo por ambos lados con un poco de aceite de oliva.", "Escurre el atún del líquido y mézclalo con la crema de ensalada.", "Finalmente, corta el bagel por la mitad y coloca la lechuga, el tomate, el huevo frito y el atún sobre el bagel."], "image_url": "/images/recipes/88.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:89", "title": "Tortitas veganas", "category": "Desayunos", "protein_g": 65, "carbs_g": 89, "fat_g": 13, "minutes": 18, "ingredients": ["1 Plátano", "50 g Harina de Centeno", "130 ml Bebida de Almendra", "2 cdita Sustituto de Huevo", "2 cdita Agua", "30 g Proteína en Polvo", "150 g Yogur de Soya", "20 g Sirope de Flor de Coco", "Canela", "Edulcorante", "0.5 Polvo de Hornear", "Sal"], "steps": ["Primero, aplasta el plátano con un tenedor en un recipiente.", "Prepara el sustituto del huevo y añádelo al plátano junto con harina de centeno, leche de almendras, polvo de proteínas, canela, edulcorante, levadura en polvo y una pizca de sal, luego mezcla.", "Precalienta una sartén.", "Remueve el yogur de soja con 25 ml de agua hasta que esté cremoso y añade la miel. Ajusta el dulzor con edulcorante adicional si lo deseas.", "Vierte la masa en la sartén para crear pancakes de unos 8 cm de diámetro. Cocina a fuego medio hasta que estén dorados por ambos lados.", "Al servir, apila los pancakes y el yogur de soja alternadamente para formar una torre."], "image_url": "/images/recipes/89.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:90", "title": "Muesli crujiente de frutas", "category": "Desayunos", "protein_g": 22, "carbs_g": 101, "fat_g": 8, "minutes": 3, "ingredients": ["300 g Yogur de Soya", "30 g Muesli", "15 g Bayas de Goji", "1 Plátano", "1 Manzana", "100 g Uvas", "100 g Frambuesas", "Canela"], "steps": ["Corta el plátano y la manzana en trozos pequeños.", "En un recipiente de vidrio, coloca capas de yogur, plátano, manzana, uvas, frambuesas y granola.", "Espolvorea bayas de goji y un poco de canela por encima."], "image_url": "/images/recipes/90.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:91", "title": "Avena instantánea con crema de frutas", "category": "Desayunos", "protein_g": 53, "carbs_g": 116, "fat_g": 12, "minutes": 10, "ingredients": ["100 g Copos de 5 cereales", "10 g Amaranto (inflado)", "25 g Proteína en Polvo (sabor Vainilla)", "150 g Yogur de Soya", "1 Plátano", "100 g Fresas", "50 g Frambuesas", "5 ml Aceite de Semilla de Lino", "Canela"], "steps": ["Hierve 220 ml de agua en un hervidor. Coloca los copos de 5 cereales y el amaranto en un recipiente.", "Añade agua, aceite de linaza, canela y la mitad del polvo de proteínas. Mezcla bien, cubre con papel de aluminio y deja reposar durante 5 minutos.", "Corta el plátano y las fresas en trozos pequeños. En un recipiente aparte, mezcla el yogur de soja con un poco de agua y el resto del polvo de proteínas para crear una crema.", "Retira el papel de aluminio del recipiente. Los copos y el amaranto ya deberían haber absorbido el agua. Extiende la crema sobre los copos y cubre con la fruta."], "image_url": "/images/recipes/91.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:92", "title": "Pizza de tomate y mozzarella", "category": "Platos principales", "protein_g": 31, "carbs_g": 68, "fat_g": 14, "minutes": 60, "ingredients": ["100 g Harina de Espelta", "50 ml Agua", "5 g Levadura", "1 cdita Aceite de Oliva", "80 g Mozzarella (light)", "1 Tomates", "Sal", "Orégano", "Albahaca"], "steps": ["Primero, mezcla la harina de espelta, la levadura, el agua, una cucharadita de aceite de oliva, una pizca de sal y orégano en un recipiente y amasa durante unos 10 minutos para formar una masa suave.", "A continuación, cubre el recipiente de la masa con un paño y déjala levar durante unos 40 minutos a temperatura ambiente.", "Estira la masa sobre una superficie enharinada, extiende con salsa de tomate y cubre con tomates y mozzarella.", "Coloca la pizza cubierta en un horno precalentado a 200°C y hornea durante unos 15 minutos.", "Finalmente, corta la pizza, adorna con orégano y albahaca, y disfruta."], "image_url": "/images/recipes/92.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:93", "title": "Boloñesa vegana", "category": "Platos principales", "protein_g": 49, "carbs_g": 156, "fat_g": 11, "minutes": 45, "ingredients": ["2 cda Pasta de Tomate", "250 g Tomates (colados)", "100 g Lentejas (rojas)", "100 g Pasta (Integral)", "1 Cebolla", "1 cda Aceite de Oliva", "150 g Pimientos", "150 g Zanahorias", "400 ml Caldo de Verduras", "150 g Apio", "Sal y Pimienta", "Albahaca"], "steps": ["Primero, cocina la pasta integral según las instrucciones del paquete.", "Pica la cebolla, el pimiento, las zanahorias y el apio, y saltéalos en una sartén honda con aceite de oliva.", "Añade las lentejas, los tomates colados, la pasta de tomate y el caldo de verduras a la sartén y cocina a fuego lento durante unos 20-25 minutos.", "Sazona con pimienta y sal, sirve la salsa sobre la pasta y adorna con albahaca."], "image_url": "/images/recipes/93.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:94", "title": "Helado proteico de bayas", "category": "Snacks y meriendas", "protein_g": 32, "carbs_g": 45, "fat_g": 4, "minutes": 5, "ingredients": ["200 g Bayas (congeladas)", "100 ml Leche (1,5% grasa)", "30 g Proteína en Polvo", "20 g Azúcar"], "steps": ["Las bayas deben estar congeladas y la leche fría. Esto resultará en una buena consistencia similar a un helado después de batir.", "Pon todos los ingredientes en una licuadora o usa una batidora de mano para mezclar."], "image_url": "/images/recipes/94.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:95", "title": "Shakshuka", "category": "Platos principales", "protein_g": 34, "carbs_g": 93, "fat_g": 25, "minutes": 20, "ingredients": ["2 Huevos", "1 Cebolla", "1 Ajo", "250 g Mezcla de Verduras", "1 cdita Aceite de Oliva", "300 g Tomates (colados)", "Sal y Pimienta", "Comino", "Pimentón", "Perejil", "150 g Pan Integral"], "steps": ["Primero, precalienta el horno a 370°F (190°C).", "Pica las verduras. Sofríe las cebollas y el ajo en una sartén profunda con aceite de oliva, luego añade las verduras restantes (excepto los tomates colados) y cocina durante unos 5 minutos. Añade un poco de agua y sazona con pimienta, sal, comino, y pimentón.", "Cuidadosamente, rompe los huevos alrededor del borde de la sartén y déjalos deslizarse sobre la salsa de tomate, posiblemente formando pequeños huecos en la salsa con una cuchara de antemano. Espolvorea un poco de sal y pimienta sobre los huevos. Coloca la sartén en el horno y hornea durante unos 8-10 minutos hasta que los huevos estén cocidos.", "Sirve con perejil y disfruta con el pan integral."], "image_url": "/images/recipes/95.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:96", "title": "Pan proteico desmenuzado", "category": "Platos principales", "protein_g": 69, "carbs_g": 111, "fat_g": 18, "minutes": 165, "ingredients": ["150 g Harina de Espelta", "50 g Proteína en Polvo (sin sabor)", "4 g Levadura Seca", "1 cda Aceite de Oliva", "75 ml Agua", "Sal", "75 g Queso Crema (light)", "30 g Queso Feta (granulado)", "Albahaca (picada)", "Ajo en Polvo"], "steps": ["Primero, amasa la harina de espelta, proteína en polvo, levadura seca, aceite de oliva y agua en un bol para formar una masa, cubre el bol con un paño y deja que la masa leve durante 2 horas.", "Precalienta el horno a 360°F (180°C), enharina la superficie de trabajo y extiende la masa en un rectángulo.", "Mezcla el queso feta, el queso crema bajo en grasa, el ajo en polvo, la albahaca y la sal en un bol y distribuye sobre la masa.", "Corta la masa cubierta en pequeños cuadrados del tamaño del molde para hornear, apílalos unos encima de otros, colócalos en el molde para hornear, y hornea durante unos 30-35 minutos en el horno."], "image_url": "/images/recipes/96.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:97", "title": "Kebab fitness vegetariano", "category": "Platos principales", "protein_g": 66, "carbs_g": 146, "fat_g": 16, "minutes": 20, "ingredients": ["0.5 Pan Plano", "180 g Trozos de Filete (vegano)", "1 Tomate", "1 Cebolla (roja)", "1 pieza Pepino", "Lechuga", "200 g Yogur (1.5% grasa)", "1 Ajo", "Sal"], "steps": ["Primero, precalienta el horno a 390°F (200°C).", "Lava y corta las verduras.", "Humedece ligeramente el pan plano y colócalo en el horno precalentado durante unos 5 minutos.", "Mientras tanto, fríe los trozos de filete vegano en una sartén antiadherente sin aceite adicional.", "Prensa el ajo en el yogur y añade una pizca de sal.", "Corta el pan plano por la mitad y luego haz un corte en el medio de cada mitad.", "Rellena los panes planos con los ingredientes y disfruta."], "image_url": "/images/recipes/97.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:98", "title": "Pan de pizza proteico", "category": "Snacks y meriendas", "protein_g": 26, "carbs_g": 33, "fat_g": 2, "minutes": 45, "ingredients": ["100 g Requesón Bajo en Grasa", "40 g Harina de Espelta", "10 g Salvado de Trigo", "2 Claras de Huevo", "1 cdita Polvo de Hornear", "Orégano", "Sal", "Tomates", "1 Ajo"], "steps": ["Primero, corta el tomate en rodajas y pica finamente el ajo.", "A continuación, pon la harina de espelta, el salvado de trigo, el requesón, el polvo de hornear, la sal y el huevo en un bol, amasa en una masa suave, extiéndelo en una bandeja para hornear forrada con papel de hornear y deja que descanse cubierto durante unos 30 minutos.", "Precalienta el horno a 360°F (180°C). Hinca pequeños hoyos en la masa con los dedos y distribuye el ajo picado, las rodajas de tomate y el orégano encima.", "Hornea la masa cubierta en el horno precalentado durante unos 20 minutos."], "image_url": "/images/recipes/98.webp", "source": "MyFitCoach — recetario proporcionado"}, {"source_key": "myfitcoach:99", "title": "Pan naan proteico", "category": "Snacks y meriendas", "protein_g": 37, "carbs_g": 55, "fat_g": 7, "minutes": 15, "ingredients": ["100 g Harina de Espelta", "25 g Proteína en Polvo (sin sabor)", "75 g Requesón Bajo en Grasa", "1 cdita Polvo de Hornear", "1 cdita Aceite de Oliva", "Sal"], "steps": ["Primero, combina todos los ingredientes en un bol y amásalos en una masa suave.", "Divide la masa en dos mitades iguales y extiéndelas sobre una superficie de trabajo enharinada en panes planos de igual tamaño.", "Cocina los panes planos en una sartén antiadherente precalentada (sin aceite adicional) por ambos lados, tapados, hasta que los naan tengan manchas marrones."], "image_url": "/images/recipes/99.webp", "source": "MyFitCoach — recetario proporcionado"}]$recetas$::jsonb) as r(source_key text,title text,category text,image_url text,minutes integer,protein_g numeric,carbs_g numeric,fat_g numeric,ingredients text[],steps text[],source text)
on conflict(source_key) do nothing;
notify pgrst,'reload schema';
